<?php $calcEvidence=$meta['evidence']??[];$calculations=$calcEvidence['calculations']??[];$checkpoint=$calcEvidence['calculation_checkpoint']??null;$calculationReviews=$calcEvidence['calculation_reviews']??[]; ?>
<?php if($calculations||$checkpoint||$calculationReviews): ?><section class="calculation-records task-brief"><h2>Reproducible calculations</h2><p class="fine">Files are inert, untrusted text. Inspect code before running it in your own tools. Checksums identify bytes; execution, reproduction and scientific validity remain self-reported.</p>
<?php if($checkpoint): ?><h3>Work checkpoint</h3><?php foreach(['completed'=>'Completed','remaining'=>'Remaining','next_action'=>'Next action','required_tools'=>'Required tools'] as $key=>$label): ?><p><strong><?=e($label)?>:</strong> <?=e($checkpoint[$key])?></p><?php endforeach ?><?php if($checkpoint['resume_from_result_id']): ?><p>Resumed from <a href="<?=e($base)?>/results/<?=e($checkpoint['resume_from_result_id'])?>">accepted progress</a>.</p><?php endif ?><?php endif ?>
<?php foreach($calculations as $calculation): ?><article><h3><?=e($calculation['title'])?></h3><p><strong>Execution status:</strong> <?=e($calculation['status'])?> · <?=e($calculation['execution_note'])?></p><?php if($admission==='accepted'): try {rc_read($r['id'],$result['id']);$download=true;}catch(HttpError){$download=false;}if($download): ?><p><a class="button secondary" href="<?=e($base)?>/results/<?=e($result['id'])?>/calculations/<?=e($calculation['id'])?>/bundle.json">Download reproducibility bundle</a></p><?php else: ?><p class="fine">Historical calculation: download withdrawn after the task revision or visibility changed.</p><?php endif;endif ?>
<details><summary>Method, environment and command</summary><?php foreach(['method','environment','command','limitations'] as $key): ?><p><strong><?=e(ucfirst($key))?>:</strong> <?=e($calculation[$key])?></p><?php endforeach ?></details>
<details><summary>Inputs, outputs and unit checks</summary><dl class="metadata"><?php foreach(['inputs','outputs'] as $key): foreach($calculation[$key] as $q): ?><dt><?=e($key.' · '.$q['id'])?></dt><dd><?=e($q['value'].' '.$q['unit'])?> · <?=e($q['file_id'].' / '.$q['locator'])?></dd><?php endforeach;endforeach ?></dl><?php foreach($calculation['unit_checks'] as $check): ?><p><strong><?=e($check['assessment'])?>:</strong> <?=e($check['input_id'].' → '.$check['output_id'])?> · <?=e($check['explanation'])?></p><?php endforeach ?></details>
<details><summary>Retained files and SHA-256 checksums</summary><?php foreach($calculation['files'] as $file): ?><h4><?=e($file['name'])?> · <?=e($file['role'])?></h4><p class="fine"><?=e($file['sha256'])?></p><pre><?=e($file['content'])?></pre><?php endforeach ?></details></article><?php endforeach ?>
<?php foreach($calculationReviews as $review): ?><article><h3>Independent calculation review · <?=e($review['verdict'])?></h3><p><?=e($review['method'])?></p><p><?=e($review['environment'])?></p><details><summary>Reproduction run log and observed outputs</summary><pre><?=e($review['run_log'])?></pre><?php foreach($review['observed_outputs'] as $q): ?><p><?=e($q['id'].': '.$q['value'].' '.$q['unit'])?></p><?php endforeach ?></details><p><a href="<?=e($base)?>/results/<?=e($review['result_id'])?>">Calculation under review</a></p></article><?php endforeach ?></section><?php endif ?>